// CONFIGURACIÓN. Es lo único que se edita en este flujo; sirve a uno o a varios clientes de Reymen.
// - reymenUrl: dirección de Reymen. n8nUrl: dirección PÚBLICA de este n8n (la que ve Twilio), sin "/" al final.
// - twilioAccountSid: consola de Twilio. El token NO va aquí para enviar: va en la credencial "Twilio" de n8n.
// - twilioAuthToken: el mismo Auth Token, SOLO para comprobar que los avisos que llegan son de Twilio (recomendado).
// - clientes: un renglón por negocio. whatsapp = su número de WhatsApp en Twilio (+52…); orgId y llave en Reymen:
//   Admin → Clientes → (cliente) → botón de webhook. La llave es secreta: no exportes ni compartas este flujo con ella.
const cfg = {
  reymenUrl: 'https://app.reymen.mx',
  n8nUrl: 'https://n8n.tu-dominio.mx',
  twilioAccountSid: 'ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
  twilioAuthToken: '',
  clientes: [
    { nombre: 'Mi negocio', whatsapp: '+528100000000', orgId: 'PEGA_AQUI_EL_ID_DE_LA_ORGANIZACION', llave: 'PEGA_AQUI_LA_LLAVE_DE_CONEXION' },
  ],
};
// Qué webhook despertó al flujo: cada uno sigue su camino en el siguiente nodo.
const ruta = $('Twilio: mensaje entrante').isExecuted ? 'entrante' : $('Reymen: enviar WhatsApp').isExecuted ? 'saliente' : 'estado';
const item = $input.first();
return [{ json: { ruta, cfg, req: item.json }, binary: item.binary }];

const crypto = require('crypto');
// Firma de Reymen (entrada /api/webhooks/n8n/*): sha256= + HMAC-SHA256 hex de "<timestamp>.<cuerpo>" con la llave del cliente.
function firmar(llave, body) {
  const ts = String(Date.now());
  return { ts, sig: 'sha256=' + crypto.createHmac('sha256', llave).update(ts + '.' + body).digest('hex') };
}
// Cuerpo crudo que llegó al webhook (opción "Raw Body"), para verificar firmas byte por byte.
function crudo(item) {
  return item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body || {});
}
// Verifica que el aviso venga de Reymen (firma de plataforma con N8N_WEBHOOK_SECRET y hora dentro de ±5 min).
function verificarReymen(item) {
  const secret = $env.N8N_WEBHOOK_SECRET;
  const h = item.json.headers || {};
  const raw = crudo(item);
  const ts = String(h['x-reymen-timestamp'] || '');
  const sig = String(h['x-reymen-signature'] || '');
  const esperado = 'sha256=' + crypto.createHmac('sha256', secret || '').update(ts + '.' + raw).digest('hex');
  if (!secret || !ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000 || sig.length !== esperado.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(esperado))) {
    throw new Error('Firma de Reymen inválida');
  }
  return JSON.parse(raw);
}

// Teléfono a formato internacional (+52 + 10 dígitos para México; otros países ya con su lada).
function e164(raw) {
  const s = String(raw || '').replace(/^whatsapp:/, '');
  const d = s.replace(/\D/g, '');
  if (d.length === 10) return '+52' + d;
  if (d.length === 13 && d.startsWith('521')) return '+52' + d.slice(3);
  if (s.trim().startsWith('+') && d.length >= 11) return '+' + d;
  if (d.length === 12 && d.startsWith('52')) return '+' + d;
  return null;
}
// Firma de Twilio (X-Twilio-Signature): base64 de HMAC-SHA1 de la URL pública + cada parámetro (ordenados) con el Auth Token.
function twilioValido(cfg, url, params, firma) {
  if (!cfg.twilioAuthToken) return true; // sin token configurado no se verifica (ver la guía)
  const data = url + Object.keys(params).sort().map((k) => k + params[k]).join('');
  const esperado = crypto.createHmac('sha1', cfg.twilioAuthToken).update(Buffer.from(data, 'utf-8')).digest('base64');
  return !!firma && firma.length === esperado.length && crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperado));
}
const twilioUrl = (cfg, c) => 'https://api.twilio.com/2010-04-01/Accounts/' + (c.twilioAccountSid || cfg.twilioAccountSid) + '/Messages.json';

// Mensaje que un cliente final escribió al WhatsApp del negocio → conversación en la bandeja de Reymen.
const { cfg, req } = $input.first().json;
const p = req.body || {};
const url = cfg.n8nUrl + '/webhook/reymen-twilio-entrante';
if (!twilioValido(cfg, url, p, (req.headers || {})['x-twilio-signature'])) throw new Error('Firma de Twilio inválida');
const numeroNegocio = e164(p.To);
const c = cfg.clientes.find((x) => e164(x.whatsapp) === numeroNegocio);
if (!c) throw new Error('El número ' + numeroNegocio + ' no está en Configuración → clientes');
const media = Number(p.NumMedia || 0);
const texto = String(p.Body || '').trim();
const contenido = texto || (media > 0 ? '📎 Envió un archivo (' + (p.MediaContentType0 || 'adjunto') + '). Ábrelo en WhatsApp.' : '');
if (!contenido || !p.MessageSid) return [];
const body = JSON.stringify({
  channel: 'whatsapp',
  contactPhone: e164(p.From) || String(p.From || '').replace(/^whatsapp:/, ''),
  contactName: p.ProfileName || undefined,
  message: { role: 'USER', content: contenido, externalId: p.MessageSid },
});
const f = firmar(c.llave, body);
return [{ json: { url: cfg.reymenUrl + '/api/webhooks/n8n/conversations', orgId: c.orgId, body, ts: f.ts, sig: f.sig, eventId: 'twilio:' + p.MessageSid } }];

