const twilioUrl = (cfg, c) => 'https://api.twilio.com/2010-04-01/Accounts/' + (c.twilioAccountSid || cfg.twilioAccountSid) + '/Messages.json';

// Respuesta escrita en la bandeja de Reymen (o por el Agente IA) → WhatsApp del cliente final, vía Twilio.
// Si algo falla, el flujo responde error y Reymen marca el mensaje como «no enviado».
const { cfg } = $input.first().json;
const reymen = verificarReymen({ json: $input.first().json.req, binary: $input.first().binary });
const d = reymen.data || {};
const c = cfg.clientes.find((x) => x.orgId === reymen.organizationId);
if (!c) throw new Error('La organización ' + reymen.organizationId + ' no está en Configuración → clientes');
const to = e164(d.contactPhone);
if (!to) throw new Error('Teléfono del contacto inválido');
const form = new URLSearchParams({ From: 'whatsapp:' + e164(c.whatsapp), To: 'whatsapp:' + to });
if (d.content) form.set('Body', String(d.content));
if (d.attachmentUrl) form.set('MediaUrl', String(d.attachmentUrl));
// Twilio avisa aquí si se entregó o se leyó; Reymen lo muestra en la bandeja.
if (d.messageId) form.set('StatusCallback', cfg.n8nUrl + '/webhook/reymen-twilio-estado?org=' + encodeURIComponent(c.orgId) + '&mid=' + encodeURIComponent(d.messageId));
return [{ json: { twilioUrl: twilioUrl(cfg, c), form: form.toString() } }];

