if (!twilioValido(cfg, url, p, (req.headers || {})['x-twilio-signature'])) throw new Error('Firma de Twilio inválida');
const MAPA = { sent: 'SENT', delivered: 'DELIVERED', read: 'READ', failed: 'FAILED', undelivered: 'FAILED' };
